package com.vandorlabs.neoforge.gear;

import java.util.*;
import net.minecraft.core.*;
import net.minecraft.core.component.DataComponents;
import net.minecraft.nbt.*;
import net.minecraft.server.level.*;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.item.*;
import net.minecraft.world.level.GameType;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.phys.*;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.event.server.ServerStartedEvent;
import net.neoforged.neoforge.event.tick.ServerTickEvent;

/** Physical supports, ordinary Survival item placement, full component cells and actual world-tick motion. */
@EventBusSubscriber(modid="vandorlabs")
public final class NativeGearFeetChecks {
    private record Case(BlockPos root,Direction mount,NativeGearDefinition arm,NativeGearDefinition foot,boolean rotate) {
        BlockPos tip(){return root.relative(mount,2);}
        int feet(){return foot==NativeGearDefinition.LARGE_WHEEL?4:foot==NativeGearDefinition.PLATE||foot==NativeGearDefinition.SKI?3:1;}
        boolean fixed(){return arm.kind==NativeGearDefinition.Kind.MOUNT;}
    }
    private static final List<Case> CASES=new ArrayList<>();private static ServerLevel world;private static Actor actor;private static int stage,ticks,checks;private static boolean running;
    private static final class Actor extends net.neoforged.neoforge.common.util.FakePlayer {Actor(ServerLevel level){super(level,new com.mojang.authlib.GameProfile(new UUID(0,2211451),"NativeGearFeet"));}}
    private static String phase(){return System.getProperty("vandorlabs.gearFeetPhase","");}
    private static void need(boolean ok,String why){checks++;if(!ok)throw new AssertionError("Native feet stage="+stage+" tick="+ticks+": "+why);}
    private static NativeGearEntity tile(Case scene){var tile=NativeGearFormation.at(world,scene.root);need(tile!=null&&!tile.inert(),"healthy root "+scene);return tile;}
    private static void position(Case scene){var point=NativeGearOrientation.point(scene.mount,-4,1,-4);actor.setPos(scene.root.getX()+point.x,scene.root.getY()+point.y,scene.root.getZ()+point.z);actor.setYRot(0);}
    private static void place(Case scene,ItemStack stack,BlockPos support,Direction face){position(scene);actor.setItemInHand(InteractionHand.MAIN_HAND,stack);need(actor.gameMode.useItemOn(actor,world,stack,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(support).add(Vec3.atLowerCornerOf(face.getNormal()).scale(.5)),face,support,false)).consumesAction(),"actual component placement "+scene+" support="+support+" face="+face);}
    private static void click(Case scene){position(scene);actor.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);need(actor.gameMode.useItemOn(actor,world,ItemStack.EMPTY,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(scene.root).add(0,0,-.5),Direction.NORTH,scene.root,false)).consumesAction(),"ordinary manual activation "+scene);}
    private static void cases(){int index=0;for(var mount:Direction.values())for(var arm:new NativeGearDefinition[]{NativeGearDefinition.EXTENDER,NativeGearDefinition.ROTATING,NativeGearDefinition.MOUNT,NativeGearDefinition.LARGE_EXTENDER,NativeGearDefinition.LARGE_ROTATING,NativeGearDefinition.LARGE_MOUNT})for(int mode=0;mode<(arm.kind==NativeGearDefinition.Kind.ROTATING?2:1);mode++)for(var foot:new NativeGearDefinition[]{NativeGearDefinition.PLATE,NativeGearDefinition.SKI,arm.size==2?NativeGearDefinition.LARGE_WHEEL:NativeGearDefinition.WHEEL}){int n=index++;CASES.add(new Case(new BlockPos(18000+n%12*20,110,18000+n/12*20),mount,arm,foot,mode==1));}need(CASES.size()==144,"six faces/sizes/extender/rotatingBothModes/fixed/threeFeet");}
    @SubscribeEvent public static void started(ServerStartedEvent event){if(phase().isEmpty())return;try{world=event.getServer().overworld();actor=new Actor(world);actor.setGameMode(GameType.SURVIVAL);cases();for(var scene:CASES)for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++){int cx=(scene.root.getX()>>4)+x,cz=(scene.root.getZ()>>4)+z;world.setChunkForced(cx,cz,true);world.getChunk(cx,cz);}if(phase().equals("read")){for(var scene:CASES){var root=tile(scene);need(root.controller()&&root.assembly().feet().size()==scene.feet(),"saved complete feet "+scene);need(root.settings().footFacing()==Direction.WEST.get2DDataValue(),"configured facing retained");need(scene.fixed()?root.progress()==1:root.progress()>0&&root.progress()<1,"saved moving phase "+scene);for(var foot:root.assembly().feet()){var at=root.getBlockPos().offset(NativeGearOrientation.vector(scene.mount,new BlockPos(foot.x,foot.y,foot.z)));var member=NativeGearFormation.at(world,at);need(member!=null&&member.mount()==scene.mount&&member.componentFrame()==scene.mount&&scene.root.equals(member.owner()),"saved foot frame/controller "+at);}}stage=10;running=true;return;}
        for(var scene:CASES){for(int x=-6;x<=6;x++)for(int y=-5;y<=6;y++)for(int z=-6;z<=6;z++)world.setBlock(scene.root.offset(x,y,z),y==-5?Blocks.STONE.defaultBlockState():Blocks.AIR.defaultBlockState(),18);world.setBlock(scene.root.relative(scene.mount.getOpposite()),Blocks.STONE.defaultBlockState(),3);var arms=new ItemStack(NativeGearBindings.ITEMS.get(scene.arm.id),2);for(int part=0;part<2;part++)place(scene,arms,scene.root.relative(scene.mount,part-1),scene.mount);need(arms.isEmpty(),"two arm sections consumed");var feet=new ItemStack(NativeGearBindings.ITEMS.get(scene.foot.id),scene.foot==NativeGearDefinition.LARGE_WHEEL?1:scene.feet());place(scene,feet,scene.root.relative(scene.mount),scene.mount);var step=NativeGearOrientation.vector(scene.mount,new BlockPos(1,0,0));var side=Direction.getNearest(step.getX(),step.getY(),step.getZ());if(scene.foot!=NativeGearDefinition.LARGE_WHEEL)for(int part=1;part<scene.feet();part++)place(scene,feet,scene.tip().offset(step.multiply(part-1)),side);need(feet.isEmpty(),"one kit per native foot component");if(scene.foot==NativeGearDefinition.LARGE_WHEEL)need(NativeGearComponents.intact(world,scene.tip()),"four-cell wheel published complete before first tick");}running=true;
    }catch(Throwable failure){failure(failure);}}
    @SubscribeEvent public static void tick(ServerTickEvent.Post event){if(!running)return;try{need(++ticks<300,"timeout pending="+CASES.stream().map(scene->scene+"="+tile(scene).progress()+"/"+tile(scene).error()).limit(5).toList());if(stage==0){for(var scene:CASES){var root=tile(scene);if(!root.controller()||root.assembly().feet().size()!=scene.feet())return;need(root.members().size()==2+scene.feet(),"complete source membership "+scene);need(root.columns().size()==1,"unsupported connected feet do not invent columns");var choices=root.settings().choices();choices.putInt("FootFacing",Direction.WEST.get2DDataValue());choices.putBoolean("RotatePayload",scene.rotate);need(root.configure(NativeGearSettings.readChoices(choices),true),"resting foot settings "+scene);for(double phase:new double[]{0,.5,1})for(var box:NativeGearGeometry.boxes(root,phase)){need(Double.isFinite(box.minX)&&box.getXsize()>0&&box.getYsize()>0&&box.getZsize()>0,"positive emitted foot collision");double reach=root.geometryReach();need(box.minX>=scene.root.getX()-reach&&box.maxX<=scene.root.getX()+reach&&box.minY>=scene.root.getY()-reach&&box.maxY<=scene.root.getY()+reach&&box.minZ>=scene.root.getZ()-reach&&box.maxZ<=scene.root.getZ()+reach,"all-pose footprint covered by loaded index");}}for(var scene:CASES)if(!scene.fixed())click(scene);stage=1;ticks=0;return;}
        if(stage==1){for(var scene:CASES){var root=tile(scene);need(!root.blocked(),"physical support stroke refused "+scene+" "+root.error());if(!scene.fixed()&&root.progress()>.55)return;}for(var scene:CASES)tile(scene).setChanged();System.out.println("[vandorlabs][gear-feet] write PASS cases="+CASES.size()+" checks="+checks+" actualSurvival/componentConsumption/unsupportedConnectedFeet/fourCellWheel/sixFaces/bothSizes/bothRotatingModes/configuredFacing/physicalSupport/movingSave");running=false;event.getServer().halt(false);return;}
        if(stage==10){for(var scene:CASES){var root=tile(scene);need(!root.blocked(),"resumed foot stroke "+scene+" "+root.error());if(!scene.fixed()&&root.progress()!=0)return;}for(var scene:CASES)if(!scene.fixed())click(scene);stage=11;ticks=0;return;}
        if(stage==11){for(var scene:CASES){var root=tile(scene);need(!root.blocked(),"post-restart reversal "+scene+" "+root.error());if(root.progress()!=1)return;}for(var scene:CASES){var root=tile(scene);var picked=NativeGearItem.pick(root.getBlockState().getBlock().asItem(),root);var data=picked.get(DataComponents.CUSTOM_DATA).copyTag();need(data.getCompound(NativeGearItem.SETTINGS).getInt("FootFacing")==Direction.WEST.get2DDataValue()&&!data.contains(NativeGearItem.RECOVERY)&&!data.toString().contains("NativeGearPayload"),"configured pick contains choices only");if(scene.foot==NativeGearDefinition.LARGE_WHEEL){var at=NativeGearComponents.cells(scene.tip(),scene.mount,world.getBlockState(scene.tip()).getValue(NativeGearBlock.FACING)).get(3);position(scene);actor.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.IRON_PICKAXE));need(actor.gameMode.destroyBlock(at),"real helper-cell mining");for(var cell:NativeGearComponents.cells(scene.tip(),scene.mount,Direction.NORTH))need(world.getBlockState(cell).isAir(),"all wheel cells removed from helper mining");var drops=world.getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new AABB(scene.tip()).inflate(4));need(drops.size()==1&&drops.getFirst().getItem().is(NativeGearBindings.ITEMS.get(scene.foot.id))&&drops.getFirst().getItem().getCount()==1,"exactly one Large Wheel kit from helper mining");}}System.out.println("[vandorlabs][gear-feet] read PASS cases="+CASES.size()+" checks="+checks+" fullNativeFootprint/frameMetadata/configuredPick/movingRestart/reversal/helperMining/singleKit");running=false;event.getServer().halt(false);}
    }catch(Throwable failure){failure(failure);}}
    private static void failure(Throwable failure){running=false;failure.printStackTrace();System.out.println("[vandorlabs][gear-feet] "+phase()+" FAIL "+failure);if(world!=null)world.getServer().halt(false);}
}
